<script setup>
import { useWorkbench } from '../composables/useWorkbench'
import { gameUrl } from '../lib/catalog'
import { validCrop } from '../lib/export'
defineProps({ showRecord: Boolean })
const { selected, draft, asset, layer, fields, table, applyDraft, resetDraft, addLayer, replaceLayer, layers, activeLayer, moveLayer, removeLayer } = useWorkbench()
</script>

<template>
        <aside class="inspector"><p class="eyebrow">INSPECTOR</p><template v-if="showRecord && selected"><h2>{{ draft.name || 'Chi tiết asset' }}</h2><p class="path">{{ selected.source || `ID ${selected.id}` }}</p><div v-if="asset" class="preview checker"><img :src="gameUrl(asset.image)" alt="Asset đang chọn"></div><a v-if="asset" class="asset-download" :href="gameUrl(asset.image)" :download="asset.image.split('/').pop()">Tải PNG: {{ asset.image.split('/').pop() }} ↓</a><p v-else class="muted">Chưa có ánh xạ ảnh cho mục này. Có thể tìm và chọn asset thủ công trong thư viện.</p><div class="actions"><button :disabled="!asset" @click="addLayer">+ Thêm lớp</button><button :disabled="!asset || !layer" @click="replaceLayer">Thay lớp chọn</button></div><template v-if="table !== 'assets'"><label v-for="field in fields" :key="field" class="field">{{ field }}<textarea v-if="String(draft[field] ?? '').length > 80" v-model="draft[field]" rows="3"></textarea><input v-else-if="typeof selected[field] === 'number'" v-model.number="draft[field]" type="number" :disabled="field === 'id'"><input v-else v-model="draft[field]" :disabled="field === 'id'"></label><div class="actions"><button class="primary" @click="applyDraft">Áp dụng nháp</button><button @click="resetDraft">Reset mục</button></div></template></template><p v-else-if="showRecord" class="muted">Chọn một asset, vật phẩm hoặc quái để xem thông tin.</p>
          <hr><div class="section-heading"><h2>Các lớp</h2><span>{{ layers.length }}</span></div><div v-for="(l, i) in layers" :key="i" class="layer-row" :class="{ active: activeLayer === i }"><button @click="activeLayer = i">{{ i + 1 }}. {{ l.name }}</button><button aria-label="Đưa lớp xuống" :disabled="i === 0" @click="moveLayer(i, -1)">↑</button><button aria-label="Đưa lớp lên" :disabled="i === layers.length - 1" @click="moveLayer(i, 1)">↓</button><button aria-label="Xóa lớp" @click="removeLayer(i)">×</button></div>
          <template v-if="layer"><label class="field">Tên lớp<input v-model="layer.name"></label><label class="inline"><input v-model="layer.visible" type="checkbox"> Hiển thị lớp</label><div class="field-grid"><label v-for="[key, label] in [['sx','Cắt X'],['sy','Cắt Y'],['w','Rộng'],['h','Cao'],['x','Vị trí X'],['y','Vị trí Y']]" :key="key" class="field">{{ label }}<input v-model.number="layer[key]" type="number" :step="key === 'x' || key === 'y' ? 0.5 : 1"></label></div><p v-if="!validCrop(layer)" class="invalid">Vùng cắt phải nằm trong ảnh và dùng số nguyên; vị trí phải là số hữu hạn. Part x4 dùng đơn vị x1.</p><p class="path">{{ layer.asset.source }}</p></template>
          <p class="muted footnote">Thay đổi chỉ tồn tại trong tab này. Xuất nháp trước khi tải lại trang. Atlas xuất giữ từng lớp riêng để Phaser có thể thay bộ phận.</p>
        </aside>
</template>
